package com.changeimpact.model;

import com.fasterxml.jackson.annotation.JsonCreator;
import com.fasterxml.jackson.annotation.JsonInclude;
import com.fasterxml.jackson.annotation.JsonProperty;

import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Detailed report generated by the ChangeImpactAnalyzer.
 */
@JsonInclude(JsonInclude.Include.NON_EMPTY)
public class ImpactReport {
    private final Set<String> changedComponentIds;
    private final Map<String, ComponentImpact> impactedComponents;
    private final Set<String> candidateTestIds;
    private final boolean cycleDetected;
    private final List<List<String>> detectedCycles;
    private final List<String> warnings;
    private final long analysisDurationMs;

    @JsonCreator
    public ImpactReport(
            @JsonProperty("changedComponentIds") Set<String> changedComponentIds,
            @JsonProperty("impactedComponents") Map<String, ComponentImpact> impactedComponents,
            @JsonProperty("candidateTestIds") Set<String> candidateTestIds,
            @JsonProperty("cycleDetected") boolean cycleDetected,
            @JsonProperty("detectedCycles") List<List<String>> detectedCycles,
            @JsonProperty("warnings") List<String> warnings,
            @JsonProperty("analysisDurationMs") long analysisDurationMs) {
        this.changedComponentIds = changedComponentIds != null ? Set.copyOf(changedComponentIds) : Collections.emptySet();
        this.impactedComponents = impactedComponents != null ? Map.copyOf(impactedComponents) : Collections.emptyMap();
        this.candidateTestIds = candidateTestIds != null ? Set.copyOf(candidateTestIds) : Collections.emptySet();
        this.cycleDetected = cycleDetected;
        this.detectedCycles = detectedCycles != null ? List.copyOf(detectedCycles) : Collections.emptyList();
        this.warnings = warnings != null ? List.copyOf(warnings) : Collections.emptyList();
        this.analysisDurationMs = analysisDurationMs;
    }

    public Set<String> getChangedComponentIds() {
        return changedComponentIds;
    }

    public Map<String, ComponentImpact> getImpactedComponents() {
        return impactedComponents;
    }

    public Set<String> getCandidateTestIds() {
        return candidateTestIds;
    }

    public boolean isCycleDetected() {
        return cycleDetected;
    }

    public List<List<String>> getDetectedCycles() {
        return detectedCycles;
    }

    public List<String> getWarnings() {
        return warnings;
    }

    public long getAnalysisDurationMs() {
        return analysisDurationMs;
    }
}
